DROP TABLE IF EXISTS `schedule_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule_versions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `period_id` bigint unsigned NOT NULL,
  `version_no` int unsigned NOT NULL,
  `status` enum('draft','ready','official','superseded','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `source` enum('manual','import','generated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `based_on_version_id` bigint unsigned DEFAULT NULL,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `published_by` bigint unsigned DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `lock_version` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `schedule_versions_period_id_version_no_unique` (`period_id`,`version_no`),
  KEY `schedule_versions_based_on_version_id_foreign` (`based_on_version_id`),
  KEY `schedule_versions_published_by_foreign` (`published_by`),
  KEY `schedule_versions_period_id_status_index` (`period_id`,`status`),
  CONSTRAINT `schedule_versions_based_on_version_id_foreign` FOREIGN KEY (`based_on_version_id`) REFERENCES `schedule_versions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `schedule_versions_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `periods` (`id`),
  CONSTRAINT `schedule_versions_published_by_foreign` FOREIGN KEY (`published_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

